window.K3_QRAW.push.apply(window.K3_QRAW, [{"id": "edu-principle|ep-03|b32|31", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-03", "chName": "", "sec": "基础练习", "no": 31, "q": "与“孟母三迁”内涵一致的选项是（", "opts": ["龙生龙，凤生凤，老鼠生儿会打洞", "师傅领进门，修行在个人", "一龙生九子，九子各不同", "染于苍则苍,染于黄则黄"], "a": 3, "exp": "本题考查影响人身心发展的因素。“孟母三迁”：孟母为了让孟子有更好的学习环境，三次搬家，最终选择了一个适合学习的环境，使孟子能够专心学习。这个故事主要强调环境对人的巨大影响。A选项，“龙生龙，凤生凤，老鼠生儿会打洞”：这一说法更多地强调遗传或先天因素对个体的影响，而不是环境。因此A选项错误。B选项，“师傅领进门，修行在个人”强调个体的主观能动性。C选项，“一龙生九子，九子各不同”，强调个体主观能动性因素的影响。D选项，“染于苍则苍，染于黄则黄”：这句话的意思是，丝放在青色的染缸里就变成了青色，放在黄色的染缸里就变成了黄色。这句话直观地体现了环境对事物的决定性影响，与“孟母三迁”中强调环境对人成长的重要影响的观点是一致的。因此，D选项正确。二、材料分析题【参考答案】影响个体身心发展的主要因素有遗传、环境、学校教育和个体的主观能动性。(1)遗传。①遗传素质是人的身心发展的生理前提，为个体的身心发展提供了可能性，也是身心发展的物质基础；遗传素质的差异对人的身心发展有一定的影响，但是遗传素质具有可塑性；遗传素质的成熟机制制约着人的身心发展水平及阶段，为一定年龄阶段的身心特点的出现提供了可能和限制。②材料中方仲永5岁时就能作诗，是个天才儿童，体现出遗传对人身心发展的作用，遗传是人身心发展的前提。(2)环境。①环境为个体的发展提供了多种可能，包括机遇、条件和对象；环境是人的身心发展的外部的客观条件，环境使遗传提供的发展可能性变成现实；环境对个体发展的影响有积极和消极之分；人在接受环境影响和作用时，也不是消极的、被动的；人具有主观能动性，人在改造环境的实践中发展着自身。②材料中方仲永所处的家庭环境主要是由其父亲决定的，其父只贪图眼前利益，让方仲永错失了学习的最佳时间，影响了发展，最后泯然众人矣；而达尔文虽然小时候不好好学习，但由于启蒙老师的影响，有个好的学习环境，最后写出了《物种起源》。这体现了环境对人身心发展的影响和作用，这种影响既可能有利也可能不利。(3）学校教育。①学校教育在人的发展中起主导作用：学校教育是有目的、有计划、有组织的培养人的活动；学校教育是通过专门训练的教师来进行的", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-03|b34|32", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-03", "chName": "", "sec": "基础练习", "no": 32, "q": "【2012年311真题12】现代学校作为一种社会机构，除了具有教育功能外，还派生出许多社会功能，其中包括（）", "opts": ["社会交往与照看功能", "个体个性化与个体社会化功能", "选拔与社会分层功能", "自我保存与自我更新功能"], "a": 2, "exp": "B选项和D选项是教育的个体功能，A选项也偏向于教育的个体功能，C选项选拔和社会分层功能体现的是教育的社会流动功能。·第三章教育与人的发展", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-03|b34|33", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-03", "chName": "", "sec": "基础练习", "no": 33, "q": "【2013年311真题13】从20世纪50年代开始.挪威各地用了将近20年的时间陆续将义务教育的结束年龄从14岁延长到16岁。有研究者根据20世纪50年代末、60年代初挪威征兵时的智力测验数据，对那段时期10.7万名应征人伍的19岁青年男子的智商得分进行研究。统计分析发现，上学9年者的智商平均得分比上学7年者高出7分，比上学8年者高出4分；经检验，差异显著。这项研究成果表明（）", "opts": ["学校教育能够提高人的智商", "当时测定智商的工具和方法相当完善", "学校教育并不能显著提高人的智商", "智商的高低影响受教育年限的长短"], "a": 0, "exp": "上学9年者的智商比上学7年和上学8年者的智商高，且差异显著，表明学校教育能提高人的智商，促进人的智力的发展。其他选项表述本身存在问题。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-03|b34|34", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-03", "chName": "", "sec": "基础练习", "no": 34, "q": "【2019年311真题4】下列教育主张中，符合教育“外论”的是（）", "opts": ["柏拉图认为教育即灵魂的转向", "卢梭主张让儿童通过实地探究明白知识是有用的", "苟子认为“人之性恶，其善者伪也”", "孟子主张“凡有四端于我者，知皆扩而充之矣"], "a": 2, "exp": "柏拉图、卢梭和孟子都是内发论的代表，荀子是外论的代表。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-03|b34|35", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-03", "chName": "", "sec": "基础练习", "no": 35, "q": "【2019年311真题8】某国招募新兵，除体检之外，还用韦氏量表进行智力测验。有学者对所得数据进行统计分析，发现获得中学文凭的新兵智力测验的平均得分，比未获得中学文凭的新兵高将近3分，经检验差异显著。这项研究结果说明（", "opts": ["军营比学校更有可能提高人的智商", "受教育水平高的新兵在军营里的智力表现更优秀", "学校教育可以促进个体的智商不断提高", ""], "a": 3, "exp": "学校教育可以使个体智商实现一定幅度的提升，D选项表述正确。A选项表述没有依据。题目提到的是平均得分，而B选项表述的是个体，且不一定受教育水平高的新兵在军营里的智力表现就更优秀。C选项错在“不断提高”。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-03|b34|36", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-03", "chName": "", "sec": "基础练习", "no": 36, "q": "【2021年311真题5】赫尔巴特认为，卢梭要求一个成年大长久地陪伴一个孩子.献出自己全部的时间和精力，这种教育的代价太昂贵了。这表明赫尔巴特不赞成（）", "opts": ["个别教育", "学校教育", "家庭教育", "国民教育"], "a": 0, "exp": "从题干来看，一个成年人长久地陪伴一个孩子，属于个别教育。赫尔巴特推崇的是学校教育。司", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|1", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 1, "q": "【2009年311真题5】马克思主义经典著作关于人的全面发展的基本含义是（", "opts": ["人的劳动能力的全面发展", "德、智、体全面发展", "人的独立个性全面发展", "人的身心全面发展"], "a": 0, "exp": "人的全面发展指在人的劳动能力全面发展的基础上，人的社会关系、体力、智力、道德精神面貌、意志、情感、个性及审美意识和实践能力等各方面的和谐统一发展。马克思从大工业生产的要求提出人的全面发展，人的全面发展是指适应大工业的劳动变换、职能更替、工人全面流动所要求的人的劳动能力或才能的全面发展，这是马克思主义人的全面发展的基本含义。马克思把劳动力或者劳动能力理解为“人的身体即活的人体中存在的、每当人生产某种使用价值时就运用的体力和智力的总和”。故选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|2", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 2, "q": "【2010年311真题5】“教育的目的在于使个人能够继续他们的教育，或者说，学习的目的和报酬，是继续不断的生长能力。”持这种观点的人，在教育目的上主张（）", "opts": ["教育准备生活说", "教育适应生活说", "教育超越生活说", "教育改造生活说"], "a": 1, "exp": "关于“教育目的”的常见学说有教育准备生活说和教育适应生活说。以斯宾塞为代表的教育准备生活说强调教育是为未来生活做准备。教育适应生活说以杜威为代表，强调教育是为了适应现在的生活，而不是为未来生活做准备。题干强调教育即生长，属于杜威的教育思想，即教育适应生活说。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|3", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 3, "q": "【2011年311真题4】把教育方针规定为“教育必须为社会主义现代化建设服务，必须与生产劳动相结合，培养德、智、体等方面全面发展的社会主义事业的建设者和接班人”的文献是（）", "opts": ["（中华人民共和国义务教育法》", "《中共中央关于教育体制改革的决定》", "（中华人民共和国教育法》", "《中国教育改革和发展纲要》"], "a": 2, "exp": "题干所指的文献是《中华人民共和国教育法》", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|4", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 4, "q": "【2012年311真题5】在课程内容选择上，斯宾塞认为科学知识最有价值，其判断依据是他的（）", "opts": ["社会本位教育目的论", "外在教育目的论", "教育准备生活说", "教育适应生活说"], "a": 2, "exp": "斯宾塞是教育准备生活说的代表人物，杜威是教育适应生活说的代表人物。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|5", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 5, "q": "【2016年311真题5】20世纪50年代末我国确立的教育方针强调（", "opts": ["教育必须与生产劳动相结合", "教育必须与社会实践相结合", "教育必须为人民服务", "教育必须为现代化建设服务"], "a": 0, "exp": "220世纪50年代末我国确立的教育方针强调教育必须与生产劳动相结合。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|6", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 6, "q": "【2015年311真题5】集中体现杜威教育目的价值取向的观点是（）", "opts": ["儿童是教育的中心，教育的各种措施都要围绕儿童加以组织", "教育过程在它之外没有终结，它终结于它自身", "社会是教育的目的，儿童是教育的起点和手段", "教育的目的就是获得更多的生长"], "a": 2, "exp": "杜威的教育目的价值取向不是完全个人本位论，也不是社会本位论，而是二者之间的调和。A选项和D选项是纯个人本位论，B选项没有体现价值取向，C选项既体现了个人取向，又体现了社会取向。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|7", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 7, "q": "【2016年311真题12】“小学1~2年级认识常用汉字1600个左右.其中800个左右会写。”这项要求属于教育目的层级中的（）", "opts": ["教育目的", "培养目标", "课程目标", "教学目标"], "a": 2, "exp": "小学1~2年级的识字目标属于语文课程目标。如果精确到每节课需要学习的汉字，则属于教学目标。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|8", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 8, "q": "【2018年311真题12】杜威所谓教育的内在目的是指（）", "opts": ["教育过程中的目的", "学校系统中的目的", "教育以人格发展为目的", "教育以知识掌握为目的"], "a": 0, "exp": "杜威所谓教育的内在目的即教育过程中的目的，这个目的就是“生长”。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|9", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 9, "q": "【2019年311真题5】中共中央总书记、国家主席、中央军委主席习近平在2018年9月10日召开的全国教育大会上强调，我国是中国共产党领导的社会主义国家，决定了我国教育必须把培养社会主义建设者和接班人作为根本任务。这表明，国家确立教育目的的首要依据是（", "opts": ["教育理论", "文化传统", "社会舆论", "政治制度"], "a": 3, "exp": "确定教育目的的首要依据是政治制度。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|10", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 10, "q": "【2020年311真题6】中华人民共和国的教育目的有一以贯之的基本价值取向，在表述上又因应形势需要而有所变化。新时代我国教育目的在于培养（", "opts": ["德智体几方面都得到发展有社会主义觉悟的有文化的劳动者", "德智体等方面全面发展的社会主义事业建设者和接班人", "德智体美等全面发展的社会主义事业建设者和接班人", "德智体美劳全面发展的社会主义事业建设者和接班人"], "a": 3, "exp": "本题考查的是新时代我国教育目的的主要内容。新时代我国教育目的在于培养德智体美劳全面发展的社会主义事业建设者和接班人。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|11", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 11, "q": "【2022年311真题5】中华人民共和国成立以来，各时期教育目的的表述虽然有所不同,但始终坚持（）", "opts": ["培养“四有”新人", "德智体美全面发展", "发展核心素养", "社会主义性质"], "a": 3, "exp": "坚持社会主义性质是我国教育目的的应有之义。中华人民共和国成立以来，我国教育目的的表述充分体现了这一点，如“有社会主义觉悟”“社会主义事业建设者和接班人”等。A、B、C选项是各时期关于教育目的的具体表述，D选项属于对教育目的的概括性表述。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|12", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 12, "q": "【2023年311真题5】斯宾塞主张，教育旨在使人掌握自我保全、谋生、养育子女、维持社会和政治关系、从事闲暇活动的知识，为人的完满生活做准备。这种教育目的的取向是（）", "opts": ["社会本位", "政治本位", "文化本位", "个人本位"], "a": 3, "exp": "根据斯宾塞的这一教育目的闸述，其强调教育应使人掌握自我保全、谋生、育儿、社会政治关系、闲活动等方面的知识，为人的完满生活做准备。这种教育目的主要立足于个人发展成长，关注个体在生活各方面所需要的知识和能力的培养。所以这种教育目的的取向属于D选项个人本位。个人本位的教育目的注重个人发展，而非社会整体利益。相比而言，社会本位强调社会需求，政治本位关注政治需求，文化本位着眼传承文化。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|13", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 13, "q": "十九大以来我国建成了世界上规模最大的教育体系，教育普及水平实现历史性跨越。取得上述成绩的根本原因是因为坚持了（）", "opts": ["以人民为中心发展教育的指导思想", "学校特色发展的指导思想", "大力发展职业教育的方针政策", "大力发展高等教育的方针政策"], "a": 0, "exp": "习近平总书记明确指出，我国教育发展的根本原因是坚持以人民为中心发展教育的指导思想。这体现了中国共产党全心全意为人民服务的宗旨。坚持这一人民利益至上、社会公平正义的指导思想，是中国教育取得历史性成就的根本所在其他选项虽然也是教育发展的重要原因，但都不是这次教育发展成就的根本原因，只有坚持以人民为中心发展教育的指导思想才是根本原因。A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|14", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 14, "q": "【2024年311真题5】下列观点中，属于“教育适应生活说”的是（", "opts": ["为人在世，可贵者在于发展，在于发展各人天赋的力量，使其经过锻炼，使人能尽其才，能在社会上达到他应有的地位。这就是教育的最终目的", "国家的教育制度只有一个目的，就是造就公民", "我们有责任把完满的生活作为要达到的目的摆在我们面前，而经常把它看清楚，以便我们在培养儿童时慎重地针对这个目的来选择施教的科目和方法", "学校主要是一种社会组织。教育既然是一种社会过程，学校便是社会生活的一种"], "a": 3, "exp": "A选项偏向教育的个人本位论，认为教育的价值在于促进个人的发展。B选项国家教育的最终目的就是培养合格的公民，屁于社会本位论的教育。C选项是斯宾塞提出的教育准备生活说的内容，他认为教育应为未来完满的生活做准备，最有价值的教育内容是科学知识793637888D选项属于教育适应生活说，杜威主张学校教育应该利用现有的生活情境作为其主要内容，帮助儿童适应眼前的生活环境，即培养能完全适应眼前社会生活的人选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b38|15", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 15, "q": "【2025年311真题5】2020年3月，中共中央、国务院发布《关于全面加强新时代大中小学劳动教育的意见》，规定在中小学设置劳动教育课程，将劳动教育内容分为（）", "opts": ["日常生活劳动、生产劳动和服务性劳动", "体力劳动、脑力劳动和数字劳动", "自由劳动、雇佣劳动和义务劳动", "个体劳动、集体劳动和义务劳动"], "a": 0, "exp": "本题为对教育文件的考查。根据《关于全面加强新时代大中小学劳动教育的意见》，劳动教育内容主要包括日常生活劳动、生产劳动和服务性劳动三类。日常生活劳动教育注重培养学生的生活自理能力和良好卫生习惯；生产劳动教育让学生体验物质财富的创造过程；服务性劳动教育则强调学生利用知识技能为他人和社会提供服务，强化社会责任感。二、分析论述题【解析】教育功能有对个体的功能，也有对社会的功能。本题需要先分析材料中的教育目的是什么。【参考答案】（1）材料提出教育的目的应该着眼于社会，改变只重视个人的传统。20世纪以来国贫民弱，须通过培养人的社会意识和能力来影响当时的经济、政治和文化的发展，改变积贫积弱的现象，论者在20世纪初就认识到了这一点，实属难能可贵。（2）论者在教育目的上具有鲜明的社会本位的价值取向。论者强调教育的目的在于谋求社会进步，定位的道德标准也是看人是否对社会发展·第四章教育目的与培养自标有促进作用。其实质上是主张社会价值高于个人价值的。教育目的的确立不应从个人本位出发，而应从社会需要出发。个人只是教育加工的原料，个人的发展必须服从于社会需要。教育的目的在于把受教育者培养成符合社会准则的公民，使受教育者社会化，保证社会生活的稳定与延续。(3)现实意义。①在学校德育目标上：教育目标不仅包括培养学生作为个体需要的基本品质，让学生遵守基本的个人道德准则，而且要考虑到学生作为社会人的身份，使学生认同社会的基本原则和基本准则。②在学校德育内容上：教育内容不仅包括个人的诚实、守信等基本做人原则，也包括社会主义核心价值观，社会主义的基本指导思想，马克思主义政治经济学、哲学基本观念等。在加强个人道德教育的同时，加强社会公德教育。③.在学校德育原则上：要坚持集体主义教育和个人教育相结合的原则。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|16", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 16, "q": "杜威在提到自己的芝加哥实验学校的经历时，说“尽管没有成功，在意图上，实验学校是‘社会中心’的。我们认为，心理发展的过程主要是一个社会的过程，一个参与的过程。...·目的在于培养个人和别人共同生活和合作共事的能力。”这表明，杜威在教育目的上(2S", "opts": ["试图调和个人与社会之间的矛盾", "坚持个人中心的观点", "认为社会是唯一的目的", "主张为完满的社会生活做准备"], "a": 0, "exp": "杜威是个人本位和社会本位的调和者，他既没有坚持个人中心，也不认为社会是唯一的目的，D选项属于斯宾塞的观点，因此只有A选项符合题意。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|17", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 17, "q": "把成年期当作一个固定的标准来看待儿童期，这种观点忘记了儿童与成人都属于发展中的个体，都在不断地生长。他们之间不是生长和不生长的区别.而是各有适合于不同情况的不同生长方式。这属于（", "opts": ["教育准备生活说", "教育适应生活说", "社会本位论", "成人本位论"], "a": 1, "exp": "题干中的观点属于B选项教育适应生活说。该观点强调儿童和成人都是发展中的个体，需要根据各自的情况和阶段选择适合的生长方式，而不是简单地将成年期作为固定的标准来看待儿童期。这种观点强调个体在不同阶段需要适应生活的不同要求和方式，以促进其全面发展。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|18", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 18, "q": "涂尔干指出“教育对社会而言只是一种工具，只是社会为了在儿童内心形成自身存在所必需的基本条件而准备的工具”，在教育目的价值取向上，这体现了（）", "opts": ["社会本位的价值取向", "个人本位的价值取向", "文化本位的价值取向", "制度本位的价值取向"], "a": 0, "exp": "涂尔干把教育视为社会的工具，教育的目的在于造就社会化的人，按照社会需要来培养人，体现的是社会本位的价值取向。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|19", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 19, "q": "白尔格门认为“教育除造就每个人，使其乐于为社会而生活，并乐于贡献其最优力量于人类生活的保存和改善以外，不能有别的目的”。这种说法体现了教育目的的价值取向是（）", "opts": ["个人本位", "社会本位", "经济本位", "文化本位"], "a": 1, "exp": "题干的意思是人是为了社会而活，人要促进社会生活的保存和改善，体现的是社会本位的价值取向。这种观点认为教育目的是以社会为本的，这样社会才能得以稳定延续并使其利益得以实现和维护。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|20", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 20, "q": "以下关于马克思主义人的全面发展的内涵，说法错误的是（", "opts": ["人的自由发展指的是人作为主体的自觉发展", "人的自由发展指的是人的天性，而不是社会关系中的自由发展", "全面而自由的发展不排厅个体形成独特的素质结构和个性特点", "全面发展指的是每个人的全面<自由、个性的发展37888"], "a": 1, "exp": "题干问的是说法错误的选项。B选项人的自由发展不仅仅指人的天性的发展，还指社会关系中的自由发展。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|21", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 21, "q": "“在教育的目的决定方面，个人不具有任何价值，个人不过是教育的原料，个人不可能成为教育的目的。”这表达的教育的价值取向是（", "opts": ["社会本位", "个人本位", "团体本位", "虚无主义"], "a": 0, "exp": "题干表达的教育的价值取向是社会本位。这种观点强调个人在教育中的地位相对较低，将个人视为教育的原料，认为个人的价值在于为社会服务和发展。因此，教育主要以社会的需求和目标为导向。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|22", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 22, "q": "明确规定教育“为谁（哪个社会、哪个阶层）培养人”，体现了教育目的对教育活动的）", "opts": ["定向功能", "调控功能", "评价功能", "指导功能"], "a": 0, "exp": "明确规定教育为谁培养人体现了教育目的对教育活动的定向功能。教育目的明确规定教育为特定社会或阶层培养人才，旨在指导教育活动朝着特定方向发展，具有明确的目标和导向。代性。故本题选A选项。个体本能需要出发，强调教育要服从人的成长规律和满足人的需要；注重教育对个人的价值；主张教育的目的是培养“自然人”，发展人的个性，增进人的价值，促使个人自我实带来了各种利益，符合个人本位论的观点，故A选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|23", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 23, "q": "教育内容的确定、教育活动形式和教育方法的选择都必须以教育目的为最高准则。这体现了教育目的的（）", "opts": ["导向功能", "调控功能", "评价功能", "反馈功能"], "a": 0, "exp": "题干所述体现了教育目的的导向功能。教育内容、教育活动形式和教育方法的选择都必须以教育目的为最高准则，即教育目的引导和指导教育实践的方向和发展。因此，正确答案是A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|24", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 24, "q": "以下不属于教育目的个人本位论的主张是（", "opts": ["个人价值高于社会价值", "个人的一切发展都有赖于社会", "教育的职能是发展人的潜在本能", "要根据个人发展的需要制定教育目的"], "a": 1, "exp": "社会本位论认为真正的个人是不存在的，只有人类才存在。个人的一切发展都有赖于社会，因此社会处于发展的中心，个人只有从属于社会才有价值，教育是实现社会目的的手段。B选项是社会本位论的看法。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|25", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 25, "q": "能在10分钟内正确完成3道四则混合运算题，这一表述属于（", "opts": ["培养目标", "教育目标", "教学目标", "课程目标"], "a": 2, "exp": "这一表述属于教学目标。教学目标是指在具体的教学活动中，为学生设定的具体、可实现的目标，如在10分钟内正确完成3道四则混合运算题。这个目标是为了指导和衡量教学过程中学生的学习表现和成就。因此，正确答案是C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-04|b40|26", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-04", "chName": "", "sec": "基础练习", "no": 26, "q": "我国全面发展教育的基本内容始终强调把（）放在最优先位置", "opts": ["德育", "智育", "体育", "美育"], "a": 0, "exp": "我国全面发展教育的基本内容始终强调把德育放在最优先位置。故本题正确答案为A选项。社会生产力发展水平的制约。怡续关注公众号[研大]永久培养目标888", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|1", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 1, "q": "【2008年311真题8】教育制度的核心部分是（", "opts": ["教育管理制度", "国民教育制度", "义务教育制度", "学校教育制度"], "a": 3, "exp": "本题属于对识记性知识的考查。学校教育制度是指一个国家各级各类学校的系统及其管理规则。学校教育制度是现代教育制度的核心。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|2", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 2, "q": "【2009年311真题6】小明的爷爷当年就读于半工半读学校，半天读书，半天劳动，既学到了系统的文化知识，又掌握了劳动技能。他接受的教育属于（永久微信19规数商88", "opts": ["正规教育", "", "非正规教育", "业余教育"], "a": 0, "exp": "学校教育属于正规教育。正规教育是由专门的教育人员、机构及运行制度所构成的教育形态。非正规教育是指没有能够形成相对独立的教育形式的教育，与生产生活高度一体化。本题的迷惑性在于“半工半读即便是半工半读，只要是学校教育，就底于正规教育.永久信9314系78.", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|3", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 3, "q": "【2009年311真题7】18一19世纪的欧洲，在社会政治、经济发展及特定历史文化背景下，逐渐形成了带有等级特权痕迹的双轨学制。其“双轨”是指（", "opts": ["公立学校系统与私立学校系统", "职业学校系统与普通学校系统", "大学一中学系统与小学一初等职业学校系统", "义务教育系统与非义务教育系统"], "a": 2, "exp": "本题属于对识记性知识的考查。双轨制包括“大学一中学系统”和“小学一初等职业学校系统”两轨。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|4", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 4, "q": "【2010年311真题3】根据（中华人民共和国教育法），我国学校教育制度包括（", "opts": ["家庭教育、学校教育、社会教育、成人教育", "学前教育、初等教育、中等教育、高等教育", "普通教育、特殊教育、专业教育、职业教育", "初等教育、中等教育、高等教育、终身教育"], "a": 1, "exp": "根据《中华人民共和国教育法》（1995年）.我国学校教育制度包括学前教育、初等教育、中等教育、高等教育。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|5", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 5, "q": "【2013年311真题6】根据《中华人民共和国教育法>的规定，下列属于我国基本教育制度的是(", "opts": ["社区教育制度", "成人教育制度", "教师教育制度", "教师资格制度"], "a": 1, "exp": "根据（中华人民共和国教育法）的规定，成人教育制度属于我国基本教育制度。我国基本教育制度有：学校教育制度、九年制义务教育制度、职业教育制度和继续教育制度（成人教育制度）国家教育考试制度、学业证书制度、学位制度、教育督导制度和学校及其他教育机构评估制度。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|6", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 6, "q": "【2017年311真题13】系统闸述了“学习化社会”的研究报告是（", "opts": ["《科尔曼报告》", "（一个称作学校的地方》", "《学会生存一教育世界的今天和明天》", "《国家处在危险之中：教育改革势在必行》"], "a": 2, "exp": "《学会生存—教育世界的今天和明天》系统阐述了“学习化社会”。A选项《科尔曼报告》由美国科尔曼教授主导，其核心内容是强调美国白人学生和黑人学生的差距不是由于他们学校的物质条件不同，而是黑人学生对自身的评价认知以及他是如何适应新环境的。他认为教育无法帮助他们改变生存环境。B选项《一个称作学校的地方》是一本关于教育领域的书籍，由塔拉·韦斯特弗所写。这本书主要描绘了韦斯特弗在学校学习的经历，以及她是如何适应这个新环境的。同时，这本书也进行了家庭教育和正式教育的对比，探讨了教育对个体成长的重要性。D选项是美国1983年颁布的法案。。第五章教育制度", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|7", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 7, "q": "【2020年311真题3】近代以来欧洲教育逐渐世俗化，这种发展特征在学校教育制度中表现为（）", "opts": ["教育对象扩大到平民阶层", "公立学校与宗教组织分离", "教育与生产劳动相结合", "义务教育的普及"], "a": 1, "exp": "，B选项公立学校与宗教组织分离是近代以来欧洲教育在学校教育制度中表现为世俗化的重要特征之一。在欧洲的近代化过程中，教育逐渐从宗教机构中独立出来，成为国家公共教育体系的一部分，出现了公立学校。近代以来欧洲教育还表现出其他特征。例如，教育的对象扩大到了平民阶层，大众化的教育开始得到发展；教育开始与生产劳动相结合，工业革命给教育带来了新的内容和形式；逐渐实现了义务教育的普及，社会普及教育的程度不断提高。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|8", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 8, "q": "【2020年311真题8】学制的基本构成要素是（）", "opts": ["学校的类型、级别和数量", "学校的类型、级别和性质", "学校的类型、级别和结构", "学校的类型、性质和结构"], "a": 2, "exp": "C选项学校的类型、级别和结构是学制的基本构成要素。学校的类型指学校按照性质和任务特点不同所具有的区别，如普通中小学、职业中小学、高等教育机构等。学校的级别指学校按照教育阶段和年限的不同划分，如幼儿园、小学、初中、高中、大学等。学校的结构指学校内部按照不同学科、专业或专业领域实行的管理和组织形式，如学制、教学计划、教学进度、课程结构和考试内容等。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|9", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 9, "q": "【2021年311真题7】根据中共中央、国务院《关于学前教育深化改革规范发展的若干意见）的规划，到2020年我国学前三年毛人园率达到85%，普惠性幼儿园覆盖率达到80%。这里的“学前教育”不属于（", "opts": ["国民教育", "终身教育", "义务教育", "基础教育"], "a": 2, "exp": "学前教育不属于义务教育，但属于基础教育，同时也属于终身教育和国民教育。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|10", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 10, "q": "见”“社会拒绝使用学校的毕业生”三种现象。其中，“社会拒绝使用学校的毕业生”现象的产生根源在于（", "opts": ["制度化教育的弊端", "非正规化教育的弊端", "学校教育的过度发展", "学习化社会的来临"], "a": 0, "exp": "A选项制度化教育的端是导致“社会拒绝使用学校的毕业生”现象的根源。联合国教科文组织在《学会生存一—教育世界的今天和明天》中指出，“教育先行”和“教育预见”指的是教育不能脱离社会和生产力的发展方向，应当预见潜在工作岗位和社会的需求，将教育与经济发展相结合；而“社会拒绝使用学校的毕业生”现象则是制度化教育的弊端。制度化教育的特点是按照固定的课程和教学进度进行教学，强调对标准化考试的应付能力，制度化的程度较高。这种教育体系通常忽略学生的自主性、创造性和解决实际问题的能力，使学生毕业后在实际应用中遇到困难，无法胜任工作。因此，造成了“社会拒绝使用学校的毕业生”的现象。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|11", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 11, "q": "【2023年311真题6】20世纪70年代以来，联合国教科文组织陆续发表了4份大型研究报告。其中，首次阐述终身教育理念的报告是（", "opts": ["（学会生存一教育世界的今天和明天）", "《教育—财富蕴藏其中>", "《反思教育：向全球共同利益的理念转变）", "《一起重新构想我们的未来：为教育打造新的社会契约）"], "a": 0, "exp": "A选项，《学会生存—教育世界的今天和明天），首次阐述终身教育的理念。B选项，《教育一财富蕴藏其中》，提出教育的经济性功能。C选项，《反思教育：向全球共同利益的理念转变》，倡导合作、互助的教育理念。D选项，《一起重新构想我们的未来：为教育打造新的社会契约》，关注教育的社会转型作用。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b45|12", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 12, "q": "【2024年311真题6】我国现代学校制度始建于清末，20世纪上半叶先后颁布过四个学制。下列选项中表述正确的是（）", "opts": ["“壬寅学制”是我国正式实施的第一个学制", "“癸卯学制”将学制分为三个阶段和七个等级", "“壬子一癸丑学制”将中学区分为初高两级", "“壬戌学制”规定小学堂男女可以同校学习"], "a": 1, "exp": "A选项错误。癸卯学制是中国近代由中央政府颁布并得到实施的第一个学制。壬寅学制没有实施。B选项正确。癸卯学制分为三段七级。三段为初等、中等、高等。七级为蒙养院、初等小学堂、高等小学堂、中学堂、高等学堂或大学预科、大学堂、通儒院。C选项错误。壬子一癸丑学制规定中等教育四年，不分级。将中学区分为初高级的是壬戌学制。D选项错误。壬子一癸丑学制规定小学男女同上学堂。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|13", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 13, "q": "【2008年311真题7】义务教育的基本内涵是：国家与社会有义务确保全体适龄儿童接受法定年限的学校教育，家长有义务送适龄子女接受法定年限的学校教育和（", "opts": ["学校有义务为适龄儿童提供公平的教育", "适龄儿童有义务接受法定年限的学校教育", "公共机构有对适龄儿童开放并进行教育的义务", "企事业单位和个人不得雇用学龄儿童"], "a": 1, "exp": "义务教育中三个“义务”的主体是：国家和社会的义务、家长的义务、儿童个人的义务。义务教育的特点是强制性、免费性、普及性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|14", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 14, "q": "【2010年311真题6】为适应改革开放和社会主义现代化建设的需要，1985年中共中央颁发《关于教育体制改革的决定），下放教育管理权，其中高等教育实行三级办学体制,这三级是指（）", "opts": ["中央、省（自治区、直辖市)市县", "中央、中心城市、市县", "中央、省（自治区、直辖市）、中心城市", "省(自治区、直辖市)中心城市、市县"], "a": 2, "exp": "本题属于对识记性知识的考查。我国高等教育实行中央、省（自治区、直辖市）中心城市三级办学的体制。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|15", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 15, "q": "【2010年311真题7】2008年，我国高等教育的毛人学率为23.3%。根据美国学者马丁·特罗的观点，我国高等教育处于（", "opts": ["精英化阶段", "大众化阶段", "普及化阶段", "全民化阶段"], "a": 1, "exp": "马丁·特罗关于高等教育发展阶段的分类：当一个国家的大学适龄青年中接受高等教育者的比例低于15%时，属于精英高等教育阶段；15%~50%，属于大众化高等教育阶段；50%以上，属于普及化高等教育阶段。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|16", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 16, "q": "【2011年311真题6】学制规定了各级各类学校的性质、任务、人学条件、教育年限以及学校之间的（", "opts": ["主导与辅助关系", "领导与从属关系", "合作与竞争关系", "衔接与分工关系"], "a": 3, "exp": "本题考查学制的定义，学制规定了各级各类学校的性质、任务、人学条件、修业年限以及学校之间的关系。学校之间的关系是衔接和分工的关系，因为在教育中不提倡重点学校的开设，所以不可能是从属、竞争、主导之类的关系。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|17", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 17, "q": "【2013年311真题11】20世纪80年代以来，我国教育改革逐渐由外延式发展转向内涵式发展。鲜明反映这种转型努力的标志性文献是（·第五章教育制度", "opts": ["《中共中央关于教育体制改革的决定》", "（中国教育改革与发展纲要》", "《中共中央、国务院关于深化教育改革，全面推进素质教育的决定》", "《国家中长期改革和发展规划纲要（2010一2020年）》"], "a": 2, "exp": "内涵式发展主要指的是素质教育的发展。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|18", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 18, "q": "【2014年311真题6】我国现行学制是（", "opts": ["单轨制", "双轨制", "三轨制", "分支型学制"], "a": 3, "exp": "我国仿照苏联，实行分支型学制。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|19", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 19, "q": "【2014年311真题11】20世纪末，为应对知识经济的挑战，我国开始特别重视（）", "opts": ["培养学生创新精神和实践能力", "学生全面掌握基础知识和基本技能", "发展职业教育", "义务教育均衡发展"], "a": 0, "exp": "进人21世纪，培养学生的创新精神和实践能力以应对时代的发展、知识经济的挑战尤为重要。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|20", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 20, "q": "【2014年311真题13】关于终身教育，以下说法不正确的是（", "opts": ["终身教育是学习化社会的基本特征", "终身教育主要是为了发展人的职业能力和素质", "终身教育涵盖了人的一生，不限于儿童和青少年时期", "终身教育既包括正规教育，也包括非正规教育和非正式教育"], "a": 1, "exp": "终身教育包括人一生中各阶段所受各种教育的综合，不是只为了发展人的职业能力和素质。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|21", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 21, "q": "【2015年311真题6】在我国现代学制中，根据培养目标的不同，一般把中学区分为（）", "opts": ["普通中学、职业中学、综合中学", "文科中学、理科中学、实科中学", "文科中学、实科中学、职业中学", "普通中学、重点中学、特色中学"], "a": 0, "exp": "本题可结合实际情况作答，我国现在的中学有普通中学、职业中学和综合中学。我国没有“实科中学”的说法，也没有单纯的文科中学和理科中学。在新高考背景下，中·第五章教育制度学开始实行一些选科制、力图打破文科和理科之间的壁垒。D选项不是“培养目标”维度下中学的区分方式。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|22", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 22, "q": "【2017年311真题6】我国1958年确立的教育方针强调（）", "opts": ["教育必须与生产劳动相结合", "全面实施素质教育", "坚持立德树人", "培养社会主义建设者和接班人"], "a": 0, "exp": "我国1958年确立的教育方针强调教育必须与生产劳动相结合。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|23", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 23, "q": "【2018年311真题6】以下关于终身教育的说法不正确的是（", "opts": ["终身教育是现代社会民主化的要求", "终身教育的原则是连续性、整体性", "终身教育是基础教育、高等教育的延续", "终身教育将学校化教育转变为社会化教育"], "a": 2, "exp": "终身教育并不是基础教育、高等教育的延续，终身教育是包括基础教育与高等教育在内的。D选项终身教育并不是否认学校教育，而是拓宽了学校教育的内涵，社会化教育的含义比学校化教育广，包含学校教育在内。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|24", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 24, "q": "【2019年311真题7】根据《中华人民共和国教育法》，国家实行学校教育制度。以下说法中正确的是（）", "opts": ["职业教育不是学校教育制度的组成部分", "学前教育是学校教育制度的组成部分", "学校教育制度不属于国家基本教育制度", "学校教育制度由全国人民代表大会颁布实施"], "a": 1, "exp": "A选项学校教育制度包括职业教育；C选项学校教育制度是国家基本教育制度；D选项学校教育制度由教育部颁布实施。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|25", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 25, "q": "【2020年311真题7】《国家中长期教育改革和发展规划纲要（2010—2020年）》提出在普通高中建立学生发展指导制度，并且根据现状和需求，特别强调对高中生加强（）", "opts": ["学业、心理和就业指导", "学业、就业和理想指导", "学业、心理和理想指导", "心理、就业和理想指导"], "a": 2, "exp": "（国家中长期教育改革和发展规划纲要（2010一2020年）>提出在普通高中建立学生发展指导制度，加强对学生理想、心理、学业等多方面的指导。/", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b47|26", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 26, "q": "【2025年311真题6】1951年10月.政务院颁布（关于改革学制的决定）.以“确定原有的和新创的各类学校的适当地位，改革各种不合理的年限与制度，并使不同程度的学校互相衔接”。这一文件规定的初等教育和中等教育阶段的学制是（", "opts": ["六三学制", "五四学制", "五三三学制", "十年一贯制"], "a": 2, "exp": "本题为对教育文件的考查，属于正确率较低的题目。文件内容较多，不建议考生备考时全文背诵、建议考生遇到相关题目时直接记忆答案。《关于改革学制的决定》规定小学的修业年限为五年，实行一贯制，取消初、高两级的分段制；中学的修业年限为六年、分初、高两级。修业年限各为三年，均得单独设立。故本题选C选项。原文件如下：一九五一年八月十日政务院第九十七次政务会议通过，一九五一年十月一日公布我国原有学制（即各级各类学校的系统）有许多缺点，其中最重要的，是工人、农民的干部学校和各种补习学校和训练班，在学校系统中没有应用的地位；初等学校修业六年并分为初高两级的办法，使广大的劳动人民子女难于受到完全的初等教育；技术学校没有一定的制度，不能适应培养国家建设人才的要求。这些缺点函须改正。在目前，全国学制的完全统一虽然还有一些困难，但是确定原有的和新创的各类学校的适当地位，改革各种不合理的年限与制度，并使不同程度的学校互相衔接，以利于广大劳动人民文化水平的提高，工农干部的深造和国家建设事业的促进，却是必要的和可能的。兹规定我国目前时期的学制如下：（一）幼儿教育实施幼儿教育的组织为幼儿园。幼儿园收三足岁到七足岁的幼儿，使他们的身心在入小学前获得健全的发育。幼儿园应在有条件的城市中首先设立，然后逐步推广（二）初等教育初等教育包括儿童的初等教育和青年、成人的初等教育。对儿童实施初等教育的学校为小学，应给儿童以全面的基础教育。对自幼失学的青年和成人实施初等教育的学校为工农速成初等学校、业余初等学校和识字学校（冬学、识字班）。甲、小学：小学的修业年限为五年，实行一贯制，取消初、高两级的分段制。入学年龄以七足岁为标准。毕业后，得经过考试升入中学或其他中等学校。为使不能升学的小学毕业生得继续受到适当的教育，小学得附设各种补习班或专业训练班。受过这种补习班或训练班教育的学生得经过考试插入中等学校的适当班次。乙、青年和成人的初等学校：1.工农速成初等学校，修业年限为二年至三年，招收工农干部和其他失学劳动者，施口：以相当于小学程度的教育。毕业后，得经过考试升入工农速成中学或其他中等学校。2.业余初等学校，招收工农劳动者和其", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-05|b49|27", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-05", "chName": "", "sec": "基础练习", "no": 27, "q": "下列选项不属于现代学制的是（", "opts": ["单轨制", "双轨制", "多轨制", "分支型学制"], "a": 2, "exp": "本题考查现代学制的类型。现代学制包括单轨制、双轨制和分支型学制。A选项，单轨制的特点是所有的学生在同样的学校系统中学习，从小学、中学到大学，各级各类学校相互衔接。单轨制最早产生于美国。B选项，双轨制的一轨自上而下，其结构是大学（后来也包括其他高等学校）中学（包括中学预备班）；另一轨自下而上，其结构是小学（后来是小学和中学)及其后的职业学校（先是与小学相连的初等职业教育，后发展为和初中连接的中等职业教育）。C选项，多轨制不属于现代学制的类型。D选项，分支型学制是20世纪上半叶苏联建立的一种学制。这是一种在初等教育阶段强调共同的基础性教育，到中等教育阶段分职业教育和普通教育两个分支的学制。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b52|1", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 1, "q": "【2007年311真题2】强调知识的内在逻辑和系统性,主张分科教学的是（）", "opts": ["经验主义课程论", "学科中心课程论", "存在主义课程论", "后现代主义课程论"], "a": 0, "exp": "赫尔巴特的三中心是教师、教材和课堂。与之对应的杜威的三中心是学生、活动和经验。B选项属于凭空捏造，C选项和D选项属于杜威的三中心。体的教材和课程。C选项“存在主义课程论”和存在主义哲学有关系，强调学生的自我生成（存在先于本质）。D选项“后现代主义课程论”反对传统的课程论，提倡解构和建构，但其本质上更多是一种解构。B选项“学科中心课程论”类似赫尔巴特的思想，强调具体的课程，采用分科教学。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b52|2", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 2, "q": "【2008年311真题9】按照美国学者古德莱德的观点，课程可以分为五个层面，除理想的课程、正式的课程、领悟的课程之外,还有（）", "opts": ["生活的课程和经验的课程", "运作的课程和经验的课程", "隐性的课程和运作的课程", "隐性的课程和生活的课程"], "a": 1, "exp": "本题考查的知识点是古德莱德的课程观，按照美国学者古德莱德的观点，课程可分为理想的课程、正式的课程、领悟的课程、运作的课程和经验的课程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b52|3", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 3, "q": "【2012年311真题7】学生必须接受“自由教育（liberaleducation)”，受过这种教育的人因为有广博的知识和理性的能力，将来也是适应力最强的、对未来做了最充分准备的优秀公民和劳动者。秉持这种观点的人在课程类型上倾向于（", "opts": ["学科中心课程", "学生中心课程", "社会中心课程", "活动中心课程"], "a": 0, "exp": "布鲁纳是结构主义课程论的代表人物。他主张“把任何知识教给任何儿童\"。自由教育是指以人为本，培养人的多方面能力和素质，鼓励学生自由思考和创造性思维的教育模式。因此，在自由教育的观念下，学生应该接受广泛的教育，以便能有更加广博的知识面和更加理性的思考能力。这一观点认为，只有通过广泛涉猎各种学科，才能够从多个角度看待问题，并能够进行综合性的思考和判断。在课程类型上，学科中心课程更加符合自由教育的教学法，因为这种课程强调学科知识的广度和深度，可以帮助学生建立扎实的基础，并掌握更加广泛的知识。同时，学科中心课程也能够帮助学生充分发展自己的创造性思维和综合能力，让他们能够更加独立地思考和解决问题，最终成为能实际应用知识的优秀公民和劳动者。B选项学生中心课程强调学生的主体性和自主性，注重培养学生的能力和素质。但是，相较于自由教育来说，学生中心课程的涉及范围和深度可能较窄，而且不同学生的学习进程和效果可能不同，也缺乏相对统一的评价标准，不能保证学生掌握的知识和能力的全面性和广度。C选项社会中心课程的关注点在于社会的需求和实际问题，更加注重学生与社会的联系。但是，社会中心课程可能会忽略传统的文化和知识的传承，也不能保证学生掌握其他学科的知识，无法提供广泛的知识面和多角度的思考方式。D选项活动中心课程强调的也是学生的主体性和自主性，注重学生的实践能力和价值观。但是，活动中心课程往往更侧重于实操和拓展，对基础知识和理论知识的传授可能不足，而理论知识和基础知识互相补充是学生全面发展的必要条件，同时学生的实践能力和价值观的培养需要基于扎实的理论知识和基础知识。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b52|4", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 4, "q": "【2022年311真题7】李老师习惯用更加精确的语言重述学生不甚清晰或不甚完整的发言，引得学生频频点头，表示那就是自己的意思。根据古德莱德的观点，这属于（）", "opts": ["正式的课程", "教师理解的课程", "理想的课程", "学生经验的课程"], "a": 3, "exp": "本题的关键句是李老师“用更加精确的语言重述学生不甚清晰或不甚完整的发言”以及“那就是自己的意思”，这表明题目强调的主体是学生而非教师，意在强调学生在课堂学习过程中所获得的个体经验。A选项强调的主体是教育行政部门；B选项强调的主体是教师；C选项强调的主体是教育研究机构、学术团体和课程专家。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b54|5", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 5, "q": "“课程的生成和发展，根本依据在于人的学习本性和潜能，课程作为进人教育领城的特殊文化，实质就是人的学习生命存在及其优化活动”。这种观点是把课程视为（", "opts": ["社会文化的再生产", "教学科目", "有计划的教学活动", "社会改造的过程"], "a": 0, "exp": "B选项教学科目，这是一个较为狭的视角，仅将课程视为教学的科目或内容，而没有提到课程与人的学习生命和社会文化的关系，7888C选项有计划的教学活动，这也是从教学实施的角度来看课程，强调课程是按照一定计划进行的教学活动，没有涉及课程与学习和文化的本质关系。D选项社会改造的过程，这是从社会发展的角度来看课程，将课程视为改变社会的一种手段，而题目更多是从课程与人的学习内涵的关系来定义课程，所以这一选项不太符合题意。题目中提到“课程作为进人教育领域的特殊文化，实质就是人的学习生命存在及其优化活动”，这是把课程看作人的学习生活和潜能实现的过程，是社会文化的再生产。A选项符合题意。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b54|6", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 6, "q": "教师以审视的眼光看待课程理论和课程实践中遇到的各种问题，对自身的行为进行反思,对出现的课程问题进行探究,对经验进行总结，体现了教师是课程的（）", "opts": ["实施者", "设计者", "研究者", "评价者"], "a": 2, "exp": "A选项“实施者”，教师作为课程的实施者，主要按照规定的教学大纲和课程标准，采用适当的教学方法给学生讲授课程内容。实施者更强调教师在课程执行过程中的作用。B选项“设计者”，教师作为课程的设计者，参与课程设置、教材编写、教学大纲制定等课程规划工作。设计者更关注教师在课程设计阶段的角色。C选项“研究者”，教师作为课程的研究者，通过反思和探究不断优化课程。本选项是正确答案。D选项“评价者”，教师作为课程的评价者，对学生学习效果和课程实施质量进行评估和检测。评价者侧重教师在课程评价方面的角色。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b54|7", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 7, "q": "杜威认为教育的手段与目的是同一过程不可分割的部分，他把课程看作（", "opts": ["知识的传授", "经验的获得", "文化再生产", "社会改造"], "a": 1, "exp": "本题考查杜威的教育思想。实用主义代表人物杜威强调教育的本质：教育即生活、教育即生长、教育即经验的改组或改造。题干强调目标与手段的统一，即在教育的过程中经验的改组与改造（经验的获得）。A选项，把课程看作知识的传授，属于知识中心课程理论的观点。C选项，把课程看作文化再生产，属于批判教育学的观点。D选项，把课程看作社会改造，属于社会改造课程理论的观点。A、C、D选项均与题意不符，故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b54|8", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 8, "q": "以下选项不属于经验主义课程论观点的是（", "opts": ["课程组织应心理学化", "课程应以儿童活动为中心", "课程内容不能超出儿童生活的范围", "课程应给儿童提供分化的、有组织的经验"], "a": 3, "exp": "经验主义课程论是以经验为中心的课程理论，强调教学要顾应学生的心理因素，发挥学生学习的主动性，发展学生的个性，并且强调学校与社会联系，以社会生活的实际来组织课程教材。因此，A、B、C选项均符合经验主义课程论的观点。D选项，给儿童提供分化的、有组织的经验，即按照学科固有的逻辑顺序组织课程，不属于经验主义课程论的观点，而是学科课程的观点。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b54|9", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 9, "q": "根据古德莱德的课程分类理论，“有关课程应该如何设计，应该达到什么样的水平和标准的想法”属于（", "opts": ["经验的课程", "理想的课程", "理解的课程", "文件课程"], "a": 1, "exp": "本题考查的是古德莱德的课程分类。美国著名课程专家古德莱德认为课程分五个层次：理想的课程、正式的课程、领悟的课程、运作的课程、经验的课程。B选项，理想的课程即由研究机构、学术团体和课程专家提出的应该开设的课程。A选项，经验的课程指的是学生在课程学习过程中实际体验到的东西。C选项，理解的课程是指任课教师对正式的课程所领悟而形成的课程。D选项，文件课程又叫作正式课程或官方课程，主要是由中央和地方教育行政组织制定、颁布和实施的课程。一般包括课程政策、课程计划（教学或教育计划）课程标准（教学或教育大纲）和课本或教科书等，主要规定主流课程理念、教育目的和培养目标、教育内容和主要教学材料。A、C、D三项均与题意不符，故本题选B选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b54|10", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 10, "q": "强调学生的兴趣，注重探究，把课程资源作为解决问题的工具，这种观点属于（", "opts": ["经验主义课程论", "学科中心主义课程论", "社会主义课程论", "后现代主义课程论"], "a": 0, "exp": "这种观点属于经验主义课程论。经验主义课程论强调学生的兴趣和体验，注重学生的实践探究，将课程资源作为解决问题的工具，以促进学生的全面发展、培养学生的实践能力。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b54|11", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 11, "q": "我国古代“六艺”和欧洲中世纪的“七艺”，所体现的课程定义是（", "opts": ["课程即学习经验", "课程即文化再生产", "课程即教学科目", "课程即社会改造的过程"], "a": 2, "exp": "本题考查的是课程的含义。A选项，课程即学习经验：杜威依据实用主义经验论，反对课程是活动或预先决定的目的这类观点，认为手段和目的是同一过程中不可分割的部分，课程不是预先决定的目的，而是学生的学习经验。学生被视为有很大潜力的、独特的学习者，学生的经验是最为重要的。学生的学习取决于他自己做了什么，而不是教师做了什么。此选项与题干不符，排除。B选项，课程即文化再生产：鲍尔斯和金蒂斯认为，任何社会文化中的课程，事实上都是该种社会文化的反映，学校教育的职责是要再生产对下一代有用的知识和价值。也就是说，课程是“从一定社会的文化里选择出来的材料”。此选项与题干不符，排除。C选项，课程即教学科目：把课程等同于教学科目，在历史上由来已久。我国古代课程有礼、乐、射、御、书、数“六艺”，欧洲中世纪的课程包括文法、修辞、辩证法、算术、几何、音乐、天文学“七艺”。在近代，斯宾塞在《什么知识最有价值》一书中最早提出“课程”一D选项，课程即社会改造的过程：巴西的弗莱雷认为，课程不是要使学生适应或顾从于社会文化，而是要帮助学生摆脱社会制度的束缚。他建议将课程的重点放在当代社会的主要问题和主要端、学生关心的社会现象，以及改造社会和社会活动规划等方面。此选项与题干不符，排除。综上所述，A、B、D三项均与题意不符，故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b56|12", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 12, "q": "【2009年311真题9】学科课程分科过细，偏重书本知识，同实际生活距离较远，不能照顾到儿童的需要和兴趣，难以发挥学生的主动性。立足于克服这些缺陷的课程是）(", "opts": ["综合课程", "核心课程", "选修课程", "活动课程"], "a": 3, "exp": "本题解题的关键在于学科课程难以重视到儿童的兴趣，活动课程更为关注儿童的兴趣。A选项综合课程和B选项核心课程是立足于学科课程的，它们试图打破学科之间的界限，在兴趣的关注点上不如活动课程。C选项选修课程仍会出现一些学科类课程，仍注重书本知识。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b56|13", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 13, "q": "【2011年311真题8】把两门或两门以上的学科内容整合在一门课程中，加强学科联）系，但不打破学科界限。这种课程属于（", "opts": ["活动课程", "核心课程", "相关课程", "融合课程"], "a": 2, "exp": "本题解题的关键是“不打破学科界限”。活动课程本身与学科课程是相对的，不是学科的整合，而核心课程和融合课程打破了学科界限。人", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b56|14", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 14, "q": "【2013年311真题7】某类课程的组织形式如下图所示，这类课程是（）有关的有关的自然知识社会知识有关的技能问题其他边缘学科", "opts": ["相关课程", "融合课程", "广域课程", "核心课程"], "a": 3, "exp": "图中显示的是以问题为中心，围绕问题相关的社会知识、技能、自然知识和其他边缘学科等开展的课程，属于核心课程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b56|15", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 15, "q": "【2016年311真题7】教育界尝试以综合课程加强学科之间及学科知识与现实生活之间的联系。典型的综合课程按照综合程度从高到低排列，其顺序为（", "opts": ["相关课程、广域课程、核心课程", "广域课程、相关课程、核心课程", "核心课程、相关课程、广域课程", "核心课程、广域课程、相关课程"], "a": 3, "exp": "综合课程是指把相关或相邻领域的几门学科的教育内容组织在一门综合的学科之中的课程，按照综合程度由高到低可以分为核心课程、广域课程、融合课程和相关课程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b56|16", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 16, "q": "【2020年311真题9】下列选项中，属于按同一分类维度划分的课程相关概念是（）", "opts": ["相关课程、融合课程、广域课程", "基础型课程、拓展型课程、研究型课程", "学科课程、活动课程、综合课程", "必修课程、选修课程、活动课程"], "a": 0, "exp": "综合课程的分类有相关课程、融合课程、广域课程和核心课程,所以选A选项。B选项的各个课程是可以交叉的，拓展型课程可以是研究型的，也可以是基础型的，不是严格按照某一维度做出的划分。C选项根据课程内容组织方式的不同，课程可分为综合课程与分科课程。其中活动课程不是同一维度。D选项根据学生选择课程权限的不同，课程可分为必修课程与选修课程。其中活动课程不是同一维度。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b56|17", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 17, "q": "【2023年311真题7】在讲解李清照词的课上，学生在学到“浓睡不消残酒”时，对于古代酒水的酒精度问题发生了兴趣。因此，老师调整了原来的教学计划，转而和学生讨论起古代词人与酒文化的主题。这堂课主要涉及的课程类型是（", "opts": ["理想的课程、正式的课程、领悟的课程", "正式的课程、领悟的课程、操作的课程", "领悟的课程、操作的课程、经验的课程", "经验的课程、操作的课程、理想的课程"], "a": 2, "exp": "理想的课程一般是专家学者提出的课程。正式的课程是教育部门制定颁布的课程。领悟的课程是教师根据教学计划和教学大纲实行的课程。在学生理解层面，则为经验的课程。根据描述，这堂课原计划讲解李清照词，但在学生提出酒精度问题时，老师调整了教学计划，和学生讨论起古代词人与酒文化的主题。这反映了教学计划需要因材施教、随机应变。老师顺应学生兴趣和问题，进行了趣味性的文化讨论，体现了教师领域的课程即领悟的课程、操作的课程与学生经验的课程，C选项正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b56|18", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 18, "q": "【2024年311真题7】将课程划分为国家课程、地方课程和校本课程，所依据的是(）", "opts": ["课程修习的要求", "课程的呈现方式", "课程内容的组织方式", "课程设计、开发与管理的主体"], "a": 3, "exp": "根据课程管理、开发主体的不同，课程可以分为国家课程、地方课程和校本课程，其他选项与题干不符，故本题选D选项。·第六章课程", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|19", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 19, "q": "以下没有打破学科界限的课程是（", "opts": ["活动课程", "核心课程", "相关课程", "融合课程"], "a": 2, "exp": "本题解题的关键是“没有打破学科界限”，只有相关课程符合这一要求，故选C选项。A选项活动课程本身与学科课程是相对的，不是学科的整合。而B选项核心课程和D选项融合课程打破了学科界限。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|20", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 20, "q": "下列选项中，不属于观念性隐性课程的是（）", "opts": ["校风", "学风", "班级管理方式", "教师的教育理念"], "a": 2, "exp": "本题考查的是隐性课程的表现形式。隐性课程是学校情景中以间接的、内隐的方式呈现的课程。主要表现形式：（1）观念性隐性课程。包括隐藏于显性课程之中的意识形态，学校的校风、学风，有关领导与教师的教育理念、价值观、知识观、教学风格、教学指导思想等。(2）物质性隐性课程。包括学校建筑、教室的布置、校园环境等。（3）制度性隐性课程。包括学校管理体制、学校组织机构、班级管理方式、班级运行方式。（4）心理性隐性课程。主要包括学校人际关系状况，师生特有的心态、行为方式等。A、B、D三项均属于观念性隐性课程，C选项班级管理方式属于制度性隐性课程，故本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|21", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 21, "q": "校本课程的优点有（②有利于通识性知识的学习③能调动教师参与课程建设的积极性④有助于学生掌握系统性知识", "opts": ["①2③", "②3④", "①③5", "2④③"], "a": 2, "exp": "本题考查的是校本课程的优点。校本课程是由学生所在学校的教师编制、实施和评价的课程，其主导价值在于通过课程展示学校的办学宗旨和特色，不一定有利于通识性知识的学习，在知识的系统性上也不如国家课程。因此，①③正确。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|22", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 22, "q": "隐性课程有多种表现形式，以下不属于隐性课程的是（）", "opts": ["教育理念", "学校建筑", "班级管理方式", "教科书"], "a": 3, "exp": "A选项教育理念属于观念性隐性课程；B选项学校建筑属于物质性隐性课程；C选项班级管理方式属于制度性隐性课程。D选项教科书是教师有意识、有目的、有计划地传授给学生的内容，属于显性课程。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|23", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 23, "q": "以直接经验为主的课程，其典型的表现形式是（", "opts": ["学科课程", "活动课程", "综合课程", "融合课程"], "a": 1, "exp": "本题考查的知识点是课程的类型。A选项，学科课程是以文化知识为基础，按照一定的价值标准，从不同的知识领域或学术领域选择一定的内容，根据知识的逻辑体系，将所选出的知识组织为学科的课程。B选项，活动课程也称经验课程，是从学生的兴趣和需要出发，以学生的主体性活动或经验为中心组织的课程。活动课程的主导价值在于使学生获得关于现实世界的直接经验和真切体验。C选项，综合课程是指打破传统的学科课程的知识领域，组合两门以上学科领域而构成的一门学科。根据课程内容的组织形式，课程可分为分科课程和综合课程。D选项，融合课程属于综合课程，是将有关学科融合为一门新的学科，融合之后，原来学科之间的界限不复存在。题干描述“以直接经验为主的课程”，其典型的表现形式是活动课程，故本题选B选项。A、C、D三项均不符合题意。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|24", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 24, "q": "某小学借助该地特有的“醒狮、龙形拳”等非遗项目，由该校体育教研室集体开发了“醒狮表演”和“龙形拳”的课程，并每年定期在校开展“我是小小传承人”系列活动。）该课程属于(", "opts": ["校本课程", "隐性课程", "国家课程", "地方课程"], "a": 0, "exp": "本题考查的知识点是课程的类型。根据课程设计开发主体的不同，可将课程分为国家课程、地方课程和学校课程（校本课程）。根据课程呈现形式，可将课程分为显性课程和隐性课程。题干所述课程开发的主体是学校，开发的课程旨在展示学校特色，属于校本课程，故本题选A选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|25", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 25, "q": "某藏区学校为保护和传承民族文化，在学校开设了民族文化课程。这种课程属于（", "opts": ["国家课程", "学科课程", "隐性课程", "校本课程"], "a": 3, "exp": "本题考查的知识点是课程的类型。A选项，国家课程是由国家教育行政部门负责编制、实施和评价的课程。B选项，学科课程又叫“分科课程”，它以有组织的学科内容作为课程组织的基础。是一种主张以学科为中心，根据知识的逻辑体系，将所选出的知识组织为学科的课程。C选项，隐性课程指学生在学校情景中无意识地获得经验、价值观、理想等意识形态内容和文化影响的课程。D选项，校本课程是由学生所在学校编制、实施和评价的课程。它是学校在确保国家课程和地方课程有效实施的前提下，针对学生的兴趣和需要，结合学校的传统优势及办学理念，充分利用学校和社区的课程资源，自主开发或选用的课程。题干中藏区的学校为保护和传承民族文化，在学校开设的课程，属于校本课程。故本题答案为D选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|26", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 26, "q": "某地区教育局组织中小学教师和高校专家团队编写了一套基于当地人文资源的读本，）这属于(", "opts": ["国家课程教材", "学校课程教材", "地方课程教材", "校本课程教材"], "a": 2, "exp": "本题考查的知识点是课程的类型。A选项中的国家课程的主导价值在于通过课程体现国家的教育意志，确保所有国民的共同基本素质。B选项中的学校课程，从狭义理解，是指在国家关于义务教育课程设置方案的框架内，于国家课程和地方课程之外的“预留地”里，学校结合自身传统和课程资源优势、针对本校学生的兴趣和需要而自主开发并实施的课程；广义的学校课程既包括学校自主开发的校本课程，又包括学校对于国家课程和地方课程的校本化实施，并整合建构出真正适合本C选项中的地方课程对该地区的中小学课程实施具有重要的导向作用，它的主导价值在于通过课程满足地方社会发展的现实需要。D选项中的校本课程指学校在确保国家课程和地方课程有效实施的前提下，针对学生的兴趣和需要，结合学校的传统和优势及办学理念，充分利用学校和社区的课程资源，自主开发或选用的课程。校本课程的主导价值在于通过课程展示学校的办学宗旨和特色。综上，本题选C选项。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b58|27", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 27, "q": "2022年版《义务教育课程方案》指出，三至七年级的艺术课程以音乐、美术为主，融人舞蹈、戏剧、影视相关内容。这表明艺术课程是一门（", "opts": ["综合课程", "分科课程", "核心课程", "经验课程"], "a": 0, "exp": "综合课程是一种多学科的课程组织模式，它强调学科之间的关联性、统一性和内在联系，其课程的主导价值在于通过相关学科的整合，促进学生认识的整体性发展，并形成把握解决问题的全面的视野与方法。艺术课程以音乐、美术为主，融人舞蹈、戏剧、影视相关内容，表明艺术课程是一门综合课程。二、材料分析题【参考答案】（1）①认知发展：小学阶段的学生处于具体运算阶段，能够借助具体事物或表象进行逻辑思维，但仍须具体事物的支持，还只能把逻辑运算应用到具体的或观察到的事物上。他们形成概念、发现问题和解决问题都需要与熟悉的物体或场景关联。初中阶段的学生进人形式运算阶段，学生的推理能力提高，思维发展到抽象逻辑推理水平，能进行假设思维，采用逻辑推理、归纳或演绎的方式解决问题。KUKU.第六章课程②情感发展：小学阶段的学生情感直接且外露，对教师、家长依赖性强，情绪多与具体事件相关。初中阶段的学生进人青春期，情感更复杂深刻，会产生自尊、焦虑等高级情感，自我意识增强，既渴望独立又在意他人评价，情绪波动较大。③社会性发展：小学阶段学生的社交以自我为中心，遵守规则多出于对成人的服从。初中阶段的学生更关注同伴群体，个体此时开始体会到自我概念问题的困扰，开始考虑我是谁的问题，开始在意自己在他人心中的形象。（2）①认知能力成熟化：高中学生处于形式运算阶段的成熟期，抽象逻辑思维和辩证思维能力突出。②学习目标明确化：高中学生学习的针对性和主动性显著增强。③学习内容专业化：高中课程内容深度和广度大幅提升，学科知识体系更系统严谨。④学习方式自主化：高中学生能自主制订学习计划，合理分配时间。(3）①学前阶段：以活动课程为主。学前教育聚焦健康、语言、社会、科学、艺术领域，需通过游戏活动、生活实践类课程，让幼儿在动手操作和互动中发展感知能力、社交能力，应寓学习于游戏之中。②小学阶段（尤其一至二年级）：活动课程与学科课程结合，侧重活动化设计。低学段可通过情境化活动课程激发学习兴趣，降低认知难度；中高学段逐渐增加学科课程比重，但仍需融人活动元素。③初中阶段：以学科课程为主，辅以综合实践活动课程。初中学生的抽象思维发展，需通过系统的学科课程（如", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|28", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 28, "q": "【2007年311真题7】泰勒认为，课程评价是为了找出结果与目标之间的差距，并利用这种反馈信息作为修订课程计划的依据。据此提出的课程评价模式是（", "opts": ["目标评价模式", "目标游离评价模式", "背景、输人、过程、结果评价模式", "差距评价模式"], "a": 0, "exp": "A选项“目标评价模式”由泰勒提出，主要内容是确定什么样的目标，选择什么样的经验，如何组织这些经验，怎样确定目标是否达成。B选项“目标游离评价模式”更注重实际效果，不讲求最初的目标。C选项“背景、输人、过程、结果评价模式”即CIPP评价模式。D选项“差距评价模式”旨在揭示计划标准与实际表现之间的差距。本题容易错选D选项，但是题干已经明确指出是泰勒的课程评价模式，而泰勒的课程计价属于专有名词，即“目标评价模式”，可直接选A选项。如何组织这些经验一怎样确定目标是否达成”，强调的是课程目标的主导作用。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|29", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 29, "q": "【2009年311真题12】按照布卢姆目标分类学的基本要求，下列选项中，不宜作为教学目标的表述是（）", "opts": ["培养学生的思维能力", "培养学生区别事实与假设的能力", "培养学生运用特定信息检验假设一致性的能力", "培养学生领会一个段落中各种观念之间的相互关系的能力"], "a": 0, "exp": "布卢姆目标分类学把学习目标分为三大领域：认知领域、情感领域和动作技能领域。按照布卢姆目标分类学，教学目标应当细化，A选项过于笼统和抽象。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|30", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 30, "q": "【2010年311真题8】主张课程评价的重点从“课程计划预期的结果”转向“课程计划的实际结果”的课程评价模式是（）", "opts": ["目标评价模式", "目标游高评价模式", "外观评价模式", "CIPP评价模式"], "a": 1, "exp": "泰勒的评价模式属于目标评价模式，其主要内容是确定什么样的目标，选择什么样的经验，如何组织这些经验，怎样确定目标是否达成。但题干强调的是由“课程", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|31", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 31, "q": "【2011年311真题12】关于如何组织课程内容的问题，泰勒在《课程与教学的基本原理》中提出的三条影响至今的基本原则是（", "opts": ["基础性、顺序性和整合性", "连续性、顺序性和整合性", "基础性、连续性和整合性", "基础性、连续性和顺序性"], "a": 1, "exp": "泰勒提出组织课程内容时必须遵循的三条基本原则是连续性、顺序性和整合性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|32", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 32, "q": "【2015年311真题7】强调“教学过程作为课程开发的过程”的课程实施取向是", "opts": ["忠实取向", "相互适应取向", "创生取向", "目标中心取向"], "a": 2, "exp": "课程实施取向有忠实取向、创生取向和相互适应取向。强调“教学过程作为课程开发的过程”属于创生取向。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|33", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 33, "q": "【2017年311真题4】某语文教师在古诗单元教学结束时，给学生布置了写七律诗的作业。根据布卢姆20世纪60年代提出的教育目标分类学框架，该作业在认知目标的分类中属于(）", "opts": ["分析", "理解", "评价", "综合"], "a": 3, "exp": "布卢姆教育目标分类学把教育目标分为认知、情感和动作三大领域。其中，认知领域的目标包括知识、领会、应用、分析、综合和评价。写七律诗的作业在认知目标的分类中属于综合。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|34", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 34, "q": "【2018年311真题7】泰勒原理由两条密切相关的基本原理组成，一条是课程编制原理,另一条是(）", "opts": ["课程实施原理", "课程设计原理后续关注公以课程组原理大］", "课程评价原理", ""], "a": 2, "exp": "泰勒享有“现代课程理论之父”“当代教育评价之父”之称。其主要成果", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b61|35", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 35, "q": "【2025年311真题7】泰勒的课程开发理论特别重视对“学校应该达成哪些教育目标”", "opts": ["对学生的研究、对当代社会生活的研究、学科专家的建议", "对学生的研究、对课程标准的研究、对当代社会生活的研究", "对学生的研究、对课程标准的研究、学科专家的建议", "对当代社会生活的研究、对课程标准的研究、学科专家的建议"], "a": 0, "exp": "泰勒在课程开发理论中明确提出，初步确立教育自标的三大核心来源为习者需求、社会发展需要、学科知识体系三个维度锚定教育目标，是泰勒目标模式的核心基础，与A选项匹配。」模拟练习", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|36", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 36, "q": "我国中小学，除了道德与法治、语文、历史三科使用统编教材外，其他学科不同程度存在各地版本不同的问题，这给中考省级统一命题带来了一定的阻力。在这种情况下，）对命题更具有参考价值(", "opts": ["课程标准", "教材", "课程方案", "课程目标"], "a": 0, "exp": "在各学科教材版本不同的情况下，课程标准对命题更具有参考价值。课程标准是规范教育教学活动的重要依据，可以提供统一的教学目标和要求，帮助确保教学内容的一致性和质量。因此，在中考省级统一命题中，课程标准可以作为参考依据，以确保命题的合理性和公平性。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|37", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 37, "q": "在新一轮义务教育课程修订过程中，要求有机融人社会主义先进文化、革命文化和中华优秀传统文化，全面落实有理想、有本领、有担当的时代新人培养要求，强化课程思想性，这体现了义务教育课程修订的（", "opts": ["问题导向", "创新导向", "目的导向", "成果导向"], "a": 2, "exp": "题干所述体现了义务教育课程修订的目的导向。有机融人社会主义先进文化、革命文化和中华优秀传统文化，全面落实有理想、有本领、有担当的时代新人培养要求，强化课程思想性，旨在实现特定的教育目标和培养特定类型的人才。因此，这体现了义务教育课程修订的目的导向。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|38", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 38, "q": "泰勒提出，组织学生的学习经验要注意课程经验的横向关系，经验的组织应有助于学生逐渐获得一种统一的观点，并把自己的行为与所学习的课程要素统一起来，这体现了课程组织时的何种原则（）", "opts": ["连续性", "顺序性", "整合性", "基础性"], "a": 2, "exp": "题干所述体现了课程组织时的整合性原则。泰勒提出的观点强调了学生学习经验的整合，使学生能够逐渐形成统一的观点，并将所学习的课程要素与自己的行为统一起来。这种整合性原则有助于提高学生对知识的理解和应用能力。。第六章课程", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|39", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 39, "q": "在道德与法治课程中，以“独立和相互依赖”为主题，在初始单元呈现家庭成员间的相关内容；随着学习的深人，依序拓展到学校、社区、国家和国际情境中的相关内容，并不断深化探讨的深度，体现的是何种课程组织形式（）", "opts": ["直线式组织", "螺旋式组织", "纵向组织", "逻辑组织"], "a": 1, "exp": "题干所述体现的课程组织形式是螺旋式组织。在道德与法治课程中，以“独立和相互依赖”为主题、从家庭成员间的相关内容开始，逐步拓展到学校、社区、国家和国际情境、不断深化探讨的深度，呈现了一种螺旋上升的学习路径，反复回顾和深化主题，使学生在不同层次上逐渐理解和应用相关概念。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|40", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 40, "q": "义务教育阶段道德与法治课程以“成长中的我”为原点，将学生不断扩大的生活和交往范围作为构建课程的基础，依据我与自身，我与自然、家庭、他人、社会，我与国家和人类文明的主题编制课程，这属于何种课程组织形式（", "opts": ["螺旋式", "直线式", "单一式", "活动式"], "a": 0, "exp": "题干所述的课程组织形式属于螺旋式。在这种组织形式下，道德与法治课程以“成长中的我”为原点，逐步扩大学生的生活和交往范围，围绕我与自身，我与自然、家庭、他人、社会，我与国家和人类文明等主题编制课程，呈现出一种螺旋上升的学习路径，不断回顾和深化主题，促使学生在不同层次上逐渐理解和应用相关概念。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}, {"id": "edu-principle|ep-06|b63|41", "bank": "dd1000", "subj": "edu-principle", "ch": "ep-06", "chName": "", "sec": "基础练习", "no": 41, "q": "“学生能够用一节课的时间完成一篇800字的议论文”体现了课程目标设计时的何种取向（）", "opts": ["行为目标取向", "生成性目标取向", "表现性目标取向", "结果目标取向"], "a": 0, "exp": "行为目标取向突出强调学生的行为。生成性的意思是不提前设定目标，而在教育过程中自然形成。表现性注重表演、展示。结果目标取向注重成绩。", "type": "单选", "star": false, "src": {"book": "丹丹1000题", "ver": "27丹丹", "page": 0}}]);
